import re

from moler.exceptions import ParsingDone, CommandFailure
from ta_moler.cmd.rtg.ws.genericrtgws import GenericRtgWs

__author__ = 'Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'dawid.gwizdz@nokia.com'


class RtgUpdate(GenericRtgWs):
    """Command for execute rtg-update procedure."""

    def __init__(self, connection, path="/opt/rtg/bin/rtg-update", options=None, update_file=None, prompt=None,
                 newline_chars=None, runner=None):
        """
        Rtg update command. To execute this script command with -file option you need run it as root.

        :param connection: moler connection to device, terminal when command is executed.
        :param path: Path to rtg-update script.
        :param options: parameter with which the command will be executed
        :param update_file: file for -file option if not given script will be run with -nofile option
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(RtgUpdate, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.path = path
        if update_file:
            self.options = f'-file {update_file}'
        else:
            self.options = '-nofile'
        if options:
            self.options = f'{options} {self.options}'

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = self.path
        if self.options:
            cmd = f"{cmd} {self.options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_file_error(line)
                self._parse_unknown_option(line)
                self._parse_successful_update(line)
            except ParsingDone:
                pass
        return super(RtgUpdate, self).on_new_line(line, is_full_line)

    # Example line: 10:32:05 [ERROR]    This script must be run as a root
    _re_error = re.compile(r'\[ERROR\]\s*(?P<ERROR>.*)')

    def _parse_error(self, line):
        """
        Parse line containing error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.search(self._re_error, line).group('ERROR')))
            raise ParsingDone

    _re_file_error = re.compile(r'Option file requires an argument')

    def _parse_file_error(self, line):
        """
        Parse option file requires an argument error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_file_error, line):
            self.set_exception(CommandFailure(self, 'Option file requires an argument'))
            raise ParsingDone

    # Example line: Unknown option: unknown
    _re_unknown_option = re.compile(r'Unknown option:\s*(?P<OPTION>.*)')

    def _parse_unknown_option(self, line):
        """
        Parse unknown option error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_unknown_option, line):
            self.set_exception(
                CommandFailure(self, f'Unknown option: {self._regex_helper.search(self._re_unknown_option, line).group("OPTION")}'))
            raise ParsingDone

    _re_successful_update = re.compile(r'YES YES YES YES!!! We did it again!!! Thanks for Your patience\.')

    def _parse_successful_update(self, line):
        """
        Parse line containing successful update message.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_successful_update, line):
            self.current_ret['STATUS'] = 'SUCCESS'
            raise ParsingDone


